/**
 * Boots a real Strapi instance for tests, against a throwaway SQLite file, without opening an HTTP
 * port. Tests talk to the Document Service, which is where the ADR-0001 rules live (the
 * `strictRelations` flag and the Document Service middleware for key uniqueness).
 *
 * Run from the `backend/` folder (`npm test`): Strapi resolves the application from the working
 * directory. The first boot compiles the TypeScript sources and takes a while.
 */
import fs from 'node:fs';
import { createRequire } from 'node:module';
import path from 'node:path';

// Strapi is CommonJS and breaks under Vite's module interop (named imports of lodash fail), so it is
// loaded with Node's own require, resolved from the backend folder.
const nodeRequire = createRequire(path.join(process.cwd(), 'package.json'));
const { compileStrapi, createStrapi } = nodeRequire('@strapi/strapi') as {
  compileStrapi(): Promise<unknown>;
  createStrapi(context: unknown): { load(): Promise<unknown> };
};

/** The small slice of the Document Service the tests use. Strings keep the tests independent of generated types. */
export interface DocumentService {
  create(params: { data: Record<string, unknown>; status?: 'draft' | 'published' }): Promise<{ documentId: string }>;
  update(params: { documentId: string; data: Record<string, unknown>; status?: 'draft' | 'published' }): Promise<{ documentId: string }>;
  publish(params: { documentId: string }): Promise<unknown>;
  delete(params: { documentId: string }): Promise<unknown>;
  findFirst(params?: { filters?: Record<string, unknown>; status?: 'draft' | 'published' }): Promise<{ documentId: string } | null>;
}

export interface TestStrapi {
  documents(uid: string): DocumentService;
  config: { get(path: string, defaultValue?: unknown): unknown };
  contentTypes: Record<string, unknown>;
  destroy(): Promise<void>;
}

const TEST_SECRETS: Record<string, string> = {
  // Fictitious values for a throwaway instance. They protect nothing.
  APP_KEYS: 'testKeyOne==,testKeyTwo==,testKeyThree==,testKeyFour==',
  ADMIN_JWT_SECRET: 'test-admin-jwt-secret', // scan-secrets: allow (fictitious test-only secret for a throwaway instance)
  API_TOKEN_SALT: 'test-api-token-salt', // scan-secrets: allow (fictitious test-only secret for a throwaway instance)
  TRANSFER_TOKEN_SALT: 'test-transfer-token-salt', // scan-secrets: allow (fictitious test-only secret for a throwaway instance)
  ENCRYPTION_KEY: 'test-encryption-key', // scan-secrets: allow (fictitious test-only secret for a throwaway instance)
  JWT_SECRET: 'test-jwt-secret',
};

export async function bootStrapi(): Promise<{ strapi: TestStrapi; dispose(): Promise<void> }> {
  const databaseFile = path.join('.tmp', `us-01-test-${process.pid}-${Date.now()}.db`);
  fs.mkdirSync('.tmp', { recursive: true });

  for (const [name, value] of Object.entries(TEST_SECRETS)) process.env[name] ??= value;
  process.env['DATABASE_CLIENT'] = 'sqlite';
  process.env['DATABASE_FILENAME'] = databaseFile;
  process.env['STRAPI_TELEMETRY_DISABLED'] = 'true';
  process.env['HOST'] = '127.0.0.1';
  process.env['PORT'] = '0';

  const context = await compileStrapi();
  const app = (await createStrapi(context).load()) as unknown as TestStrapi;

  return {
    strapi: app,
    async dispose() {
      // Strapi's shutdown calls process.removeAllListeners(), which would also remove the listeners
      // the test runner's worker uses to talk to Vitest. Put them back afterwards.
      const saved = process.eventNames().map((name) => [name, [...process.listeners(name as NodeJS.Signals)]] as const);
      try {
        await app.destroy();
      } finally {
        process.removeAllListeners();
        for (const [name, listeners] of saved) {
          for (const listener of listeners) process.on(name as NodeJS.Signals, listener as NodeJS.SignalsListener);
        }
      }
      for (const suffix of ['', '-journal', '-wal', '-shm']) fs.rmSync(`${databaseFile}${suffix}`, { force: true });
    },
  };
}
import { afterAll, beforeAll, describe, expect, it } from 'vitest';
import { bootStrapi, type DocumentService, type TestStrapi } from './helpers/strapi';

/**
 * US-01-T-38: the ADR-0001 Strapi rules for the `form-field` content type.
 *
 *  - `key` is unique per country (Document Service middleware, US-01-T-34): a second field with
 *    the same key in the same country is rejected, in the other country it is accepted.
 *  - A `form-field` has a required `country` relation and `documents.strictRelations: true`:
 *    publishing one without a country is rejected.
 *
 * Fictitious data only. Keys are prefixed "probe" so they never collide with the seed.
 */

const COUNTRY = 'api::country.country';
const FORM_FIELD = 'api::form-field.form-field';

describe('US-01-AC-01 / US-01-AC-14 ADR-0001 form-field rules (key per country, required country)', () => {
  let strapi: TestStrapi;
  let dispose: () => Promise<void>;
  let countries: DocumentService;
  let fields: DocumentService;
  let colombia: string;
  let chile: string;
  const created: string[] = [];

  /** A country by its natural key, created when the seed has not already created it. */
  async function ensureCountry(code: string, name: string, currencyCode: string, locale: string, sortOrder: number): Promise<string> {
    const existing = await countries.findFirst({ filters: { code }, status: 'published' });
    if (existing) return existing.documentId;
    const made = await countries.create({ data: { code, name, currencyCode, locale, sortOrder }, status: 'published' });
    return made.documentId;
  }

  function fieldData(key: string, countryDocumentId?: string): Record<string, unknown> {
    return {
      key,
      label: 'Campo de prueba',
      type: 'text',
      isRequired: false,
      sortOrder: 10,
      errorMessage: 'Revisa este campo.',
      ...(countryDocumentId ? { country: { connect: [countryDocumentId] } } : {}),
    };
  }

  async function createField(key: string, country: string | undefined, status: 'draft' | 'published' = 'published'): Promise<string> {
    const made = await fields.create({ data: fieldData(key, country), status });
    created.push(made.documentId);
    return made.documentId;
  }

  beforeAll(async () => {
    const booted = await bootStrapi();
    strapi = booted.strapi;
    dispose = booted.dispose;
    // A readable failure while the content types are not defined yet (US-01-T-15, US-01-T-16).
    expect(Object.keys(strapi.contentTypes), 'the content types of ADR-0001 must exist').toEqual(
      expect.arrayContaining([COUNTRY, FORM_FIELD]),
    );
/**
 * Router config for every content API router (ADR-0002, US-01-AC-28): the published-only
 * middleware runs after Strapi's authentication on each read action, so it can read the auth
 * result. A new content type's router MUST use this config.
 *
 * It is a FUNCTION on purpose: `createCoreRouter` stores `config[action]` as the route's own
 * `config`, and Strapi then mutates it in place (`defaultsDeep` adds `auth.scope: [<handler>]`).
 * A module-level constant would be one object shared by every router, so the first router to be
 * registered would fix the scope for all of them (a `form-field` route would require the
 * `country` scope, and the ADR-0005 token got 403). Each call returns fresh objects.
 *
 * Reads only: the rule strips draft/publication parameters from unauthenticated reads. Create,
 * update and delete are never reachable without a token that carries that exact action (the public
 * role has no write action, see bootstrap), and a valid token keeps its parameters anyway, so the
 * middleware would be a no-op there.
 */
export const publishedOnlyConfig = () => ({
  config: {
    find: { middlewares: ['global::published-only'] },
    findOne: { middlewares: ['global::published-only'] },
  },
});

